import './DataTable.css';

export type Row = {
  id: string;
  cells: string[];
};

type DataTableProps = {
  rows: Row[];
  loading: boolean;
};

const PLACEHOLDER_COUNT = 5;
const placeholderRows = Array.from({ length: PLACEHOLDER_COUNT }, (_, i) => i);

export function DataTable({ rows, loading }: DataTableProps): JSX.Element {
  return (
    <table className="data-table" role="table">
      <thead>
        <tr>
          <th scope="col">Name</th>
          <th scope="col">Value</th>
        </tr>
      </thead>
      <tbody>
        {loading
          ? placeholderRows.map((i) => (
              <tr key={i} className="data-table-row data-table-row--placeholder">
                <td className="data-table-cell">
                  <span className="data-table-shimmer" />
                </td>
                <td className="data-table-cell">
                  <span className="data-table-shimmer" />
                </td>
              </tr>
            ))
          : rows.map((row) => (
              <tr key={row.id} className="data-table-row">
                {row.cells.map((cell, idx) => (
                  <td key={idx} className="data-table-cell">
                    {cell}
                  </td>
                ))}
              </tr>
            ))}
      </tbody>
    </table>
  );
}
